import { lazy, Suspense, useState } from "react";
import { Button, Skeleton } from "@heroui/react";

const SalesChart = lazy(() =>
  import("./SalesChart").then((m) => ({ default: m.SalesChart })),
);

export const ChartSection = (): JSX.Element => {
  const [showChart, setShowChart] = useState<boolean>(false);

  return (
    <section className="flex flex-col gap-3">
      <Button
        variant="primary"
        onPress={() => setShowChart(true)}
        isDisabled={showChart}
      >
        {showChart ? "Loaded" : "Open chart"}
      </Button>
      {showChart ? (
        <Suspense
          fallback={<Skeleton className="h-64 w-full rounded-2xl" />}
        >
          <SalesChart />
        </Suspense>
      ) : null}
    </section>
  );
}
```

Why the height must match: if `fallback` doesn't have a fixed height (or is `null`), that slot starts at height 0; once the chunk loads and the real `SalesChart` (256px) swaps in, everything below it gets pushed down — that's exactly a layout shift, which raises CLS and feels janky. Because the fallback already reserves the exact 256px the real widget will occupy, swapping in only changes the CONTENT inside that slot and never changes the LAYOUT of surrounding elements, so this swap's layout-shift contribution is zero.

