type ChargeResult =
    | { orderId: string; charged: true }
    | { orderId: string; charged: false; reason: string }

export async function chargeOrder(id: string): Promise<ChargeResult> {
    // startActiveSpan nests this span under the currently-active (auto HTTP) span
    // AND makes it the active context for everything awaited inside the callback.
    return tracer.startActiveSpan("orders.charge", async (span) => {
        span.setAttribute("order.id", id)
        try {
            // Inject the CURRENT active trace context into outgoing headers using
            // the standard OTel propagator — never hand-build the traceparent string.
            const headers: Record<string, string> = { "Content-Type": "application/json" }
            propagation.inject(context.active(), headers)

