                const errBody = await res.text()
                const err = new Error(`payment gateway rejected: ${errBody}`)
                span.recordException(err)
                span.setStatus({ code: SpanStatusCode.ERROR, message: err.message })
                return { orderId: id, charged: false as const, reason: err.message }
            }

            span.setStatus({ code: SpanStatusCode.OK })
            return { orderId: id, charged: true as const }
        } catch (error: unknown) {
