const USERS_KEY = ["users"] as const

export const useUserNameMutation = () => {
    const qc = useQueryClient()

    const mutation = useMutation({
        mutationFn: patchUser,
        onMutate: async (vars: { id: number; name: string }) => {
            // Step 1: cancel any in-flight refetches so they can't overwrite the optimistic write
            await qc.cancelQueries({ queryKey: USERS_KEY })
            // Step 2: snapshot BEFORE overwriting — this is the lifeline for rollback
            const previous = qc.getQueryData<User[]>(USERS_KEY)
            // Step 3: optimistic write — the UI changes immediately since the component renders from cache
            qc.setQueryData<User[]>(USERS_KEY, (old) =>
                (old ?? []).map((u) => (u.id === vars.id ? { ...u, name: vars.name } : u)),
            )
            // Return the snapshot as ctx for onError/onSettled to reuse
            return { previous }
        },
        onError: (err, _vars, ctx) => {
            // Rollback: write the exact snapshotted value back into the cache
            if (ctx?.previous) {
                qc.setQueryData(USERS_KEY, ctx.previous)
            }
            // Let the user know the operation failed, not just silently revert
            toast.danger("Server error", {
                description: (err as Error).message,
            })
        },
        onSettled: () => {
            // Runs on both success and error: reconcile the cache with the server's truth
            void qc.invalidateQueries({ queryKey: USERS_KEY })
        },
    })

    return mutation
}
```
The three hooks satisfy the three requirements exactly. `onMutate` must follow the cancel → snapshot → write order because each step depends on the one before it: cancel first so an in-flight `GET` (triggered by an expired `staleTime` or the tab regaining focus) can't resolve later and overwrite the optimistic write just set; the snapshot must be taken before `setQueryData` runs, since the old cached value is gone the moment the write happens — snapshotting late means snapshotting the wrong thing. `return { previous }` is mandatory: TanStack Query uses exactly this returned object as `ctx` for `onError`/`onSettled`; forgetting the return makes `ctx` always `undefined` and the rollback silently fails (a classic bug). `onError` does exactly two things: writes the snapshot back into the cache (rolling back the data) and fires a toast (telling the user the operation failed) — rolling back the data correctly doesn't mean the user knows what happened, so both are needed. `onSettled` runs on EVERY outcome (success and error) because the optimistic write only guessed part of the data (the name) — the server might change other fields too (timestamp, version); `invalidateQueries` is the final reconciliation step that makes the cache exactly match the server regardless of whether `onMutate`'s guess was right or wrong. To verify: call the mutation with the server returning 200 and assert the UI keeps the new name after `onSettled`'s refetch completes; call it with a forced-fail flag (500) and assert the UI reverts exactly to the old name while the "Server error" toast appears — without the failure-path test, there's no way to be confident the rollback actually works.

