async storeChunk(sha256: string, data: Buffer): Promise<{ objectKey: string, deduped: boolean }> {
    const existing = await this.chunkDedupRepo.findOne({ where: { sha256 } })
    if (existing) {
        // HIT: content already exists — just bump refCount, never rewrite the object.
        await this.chunkDedupRepo.increment({ sha256 }, "refCount", 1)
        return { objectKey: existing.objectKey, deduped: true }
    }

    // MISS: write the REAL object first, only create the row once the write succeeds.
    const objectKey = `objects/${sha256.slice(0, 2)}/${sha256}`
    await this.objectStorage.put(objectKey, data)
    await this.chunkDedupRepo.insert({ sha256, objectKey, refCount: 1 })
    return { objectKey, deduped: false }
}

async releaseChunk(sha256: string): Promise<void> {
    // Only decrement refCount, never let it go negative; never delete the object immediately even at 0.
    await this.chunkDedupRepo
        .createQueryBuilder()
        .update()
        .set({ refCount: () => "GREATEST(ref_count - 1, 0)" })
        .where("sha256 = :sha256", { sha256 })
        .execute()
    // Actual object deletion is left to a periodic GC job that scans
    // refCount = 0 rows after a safety buffer before deleting.
}
```
`storeChunk` checks `sha256` first: if a row already exists (HIT), it just increments `refCount` atomically and returns the existing `objectKey`, never calling `objectStorage.put` again since the content already exists. If it doesn't exist (MISS), it must write the real object to storage FIRST, then `insert` the `chunk_dedup` row with `refCount: 1` — this order guarantees no row ever points at an object that was never written. `releaseChunk` only decrements `refCount` via `GREATEST(ref_count - 1, 0)` so it never goes negative, and crucially: it never deletes the object even when `refCount` hits 0. The reason is that many uploads can point at the same object via dedup; deleting immediately could race with another request currently in the middle of a `storeChunk` HIT (incrementing refCount), losing an object for a reference that's still alive. The actual deletion should be left to a periodic GC process that scans `refCount = 0` rows after a safety buffer before deleting — separating "mark as unreferenced" from "physically delete" avoids the race.

