function pageRank(
    nodes: string[],
    inLinks: Map<string, string[]>,
    outDegree: Map<string, number>,
    damping = 0.85,
    tolerance = 1e-6,
    maxIterations = 100,
): Map<string, number> {
    const n = nodes.length
    let rank = new Map(nodes.map((u) => [u, 1 / n]))

    for (let iter = 0; iter < maxIterations; iter++) {
        // Dangling correction: rank held by any node with NO outlinks must be
        // redistributed evenly across the whole graph, or total rank shrinks every round.
        let danglingSum = 0
        for (const u of nodes) {
            if ((outDegree.get(u) ?? 0) === 0) danglingSum += rank.get(u)!
        }
        const danglingShare = (damping * danglingSum) / n

        const nextRank = new Map<string, number>()
        let maxDelta = 0
        for (const u of nodes) {
            let incoming = 0
            for (const v of inLinks.get(u) ?? []) {
                incoming += rank.get(v)! / (outDegree.get(v) ?? 1)
            }
            const value = (1 - damping) / n + damping * incoming + danglingShare
            nextRank.set(u, value)
            maxDelta = Math.max(maxDelta, Math.abs(value - rank.get(u)!))
        }

        rank = nextRank
        if (maxDelta < tolerance) break
    }

    return rank
}
```
The loop initializes every node at `1/N`, then iterates up to `maxIterations` rounds. Each round, the FIRST step computes `danglingSum` — the total rank of EVERY node with `outDegree = 0` from the PREVIOUS round — then divides it evenly by `n` after multiplying by `damping`, giving `danglingShare` added to EVERY node in the current round; without this step, a dangling node's rank mass vanishes each round and total rank shrinks, breaking the algorithm's correctness. For each node `u`, the recurrence adds `(1-damping)/n` (the "teleport" term ensuring no node ever ranks exactly 0, also acting as spider-trap insurance), plus the sum of `PR(v)/outDegree(v)` over every node `v` pointing into `u`, plus `danglingShare`. The stopping condition uses the L-infinity delta (`maxDelta`) between two consecutive rounds against `tolerance`, always with an upper bound `maxIterations` so it never loops forever if the graph doesn't converge to that threshold — it returns the rank from the last round regardless of whether it formally `converged`, since the values are already very close to the stable distribution.

