async function acquireLock(clientId: string): Promise<{ token: number }> {
    // INCR on a durable key (Redis/Postgres sequence) — never an in-memory
    // counter, since it resets on service restart, sending the token backward.
    const token = await redis.incr("fencing:token:counter")
    return { token }
