// write: the storage layer — only compares two integers, knows nothing about the lock above it.
let lastSeenWatermark = 0

async function write(fencingToken: number, data: string): Promise<{ ok: boolean, reason?: string }> {
    if (fencingToken <= lastSeenWatermark) {
        return { ok: false, reason: "stale fencing token" }
    }

    await storage.persist(data) // write the real data FIRST

    // Only update the watermark AFTER a successful write, so it always
    // reflects the most recent legitimate writer that actually completed.
    lastSeenWatermark = fencingToken
    return { ok: true }
}
```
