        const ids = [fromAccountId, toAccountId].sort()
        const locked = await client.query<{ id: string; balance: string }>(
            "SELECT id, balance FROM account WHERE id = ANY($1) ORDER BY id FOR UPDATE",
            [ids],
        )
        const from = locked.rows.find((r) => r.id === fromAccountId)
        const to = locked.rows.find((r) => r.id === toAccountId)
        if (!from || !to) throw new Error("account not found")

        const bal = BigInt(from.balance)
        if (bal < amount) {
            await client.query("ROLLBACK")
            throw new Error("insufficient balance")
        }

        try {
            // 2. Unique index (txn_id, account_id, direction) is the idempotency mechanism —
            // not an app-level check. A concurrent duplicate INSERT raises 23505.
            await client.query(
                `INSERT INTO ledger_entry (txn_id, account_id, direction, amount)
                 VALUES ($1, $2, 'DEBIT', $3), ($1, $4, 'CREDIT', $3)`,
                [txnId, fromAccountId, amount.toString(), toAccountId],
            )
        } catch (err) {
            const code = (err as { code?: string }).code
            if (code === "23505") {
                await client.query("ROLLBACK")
                return { status: "replayed", txnId }
            }
            throw err
        }

        // 3. Same transaction as the ledger insert — atomic with it.
        await client.query("UPDATE account SET balance = balance - $1 WHERE id = $2", [amount.toString(), fromAccountId])
