import { createHash } from "node:crypto"

const TTL_SECONDS = 86400 // must exceed the client's max retry window

function bodyHash(rawBody: string): string {
    return createHash("sha256").update(rawBody).digest("hex")
}

async function handleWebhook(
    idempotencyKey: string,
    rawBody: string,
    runSideEffect: (body: string) => Promise<object>,
): Promise<{ status: number; body: object }> {
    const hash = bodyHash(rawBody)
    const cacheKey = `hook:idem:${idempotencyKey}:${hash}`
    const conflictKey = `hook:idem:hash:${idempotencyKey}`

    // (1) Cache hit -> return the original response verbatim, no side-effect re-run.
    const cached = await redis.get(cacheKey)
    if (cached !== null) {
        return { status: 200, body: JSON.parse(cached) }
    }

    // (2) Same key, different body -> reject as conflict instead of silently
    // returning (or re-running) with the wrong payload.
    const priorHash = await redis.get(conflictKey)
    if (priorHash !== null && priorHash !== hash) {
        return { status: 409, body: { error: "Idempotency-Key reused with a different body" } }
    }

    // Publish the body-hash gate before racing on the actual side-effect key,
    // so a concurrent conflicting-body request also sees it.
    await redis.set(conflictKey, hash, "EX", TTL_SECONDS, "NX")

    // (3) True cache-miss: run the side-effect once, then atomically claim the
    // cache key. Only the race winner's SET succeeds.
    const result = await runSideEffect(rawBody)
    const payload = JSON.stringify(result)
    const won = await redis.set(cacheKey, payload, "EX", TTL_SECONDS, "NX")
    if (won === null) {
        // Someone else won the race while we were computing — read THEIR value
        // instead of trusting our own (possibly duplicate) side-effect result.
        const winner = await redis.get(cacheKey)
        return { status: 200, body: JSON.parse(winner ?? payload) }
    }
    return { status: 200, body: result }
}
```
The cache key combines both `idempotencyKey` and `sha256(rawBody)`, so a request replaying the exact same body always hits the same entry, while a request reusing the key with a different body gets a different `cacheKey` — which is why a separate `conflictKey` (storing only the hash, not the response) is needed to detect that and return 409 instead of silently falling into the cache-miss branch and re-running the side-effect. The key piece protecting against the race in (3) is `SET ... NX` — it is atomic at the Redis level: whichever request writes the cache key FIRST is the "winner"; the loser (even if both already finished running `runSideEffect` before writing) reads back the winner's value and returns that, guaranteeing the client always sees ONE single response for a given (key, body) pair no matter how many concurrent calls arrive. The TTL must exceed the client's maximum retry window, and for a side-effect that cannot be safely replayed (like charging money), add a durable unique constraint at the business layer instead of relying entirely on the ephemeral cache.

