    room: string
    messageId: string
    payload: unknown
    seq: number
}

const DEDUP_TTL_SECONDS = 3600

function dedupKey(room: string, messageId: string): string {
    return `chat:dedup:${room}:${messageId}`
}
function seqKey(room: string): string {
    return `chat:seq:${room}`
}
function logKey(room: string): string {
    return `chat:log:${room}`
}

async function accept(
    room: string,
    messageId: string,
    payload: unknown,
): Promise<{ duplicate: boolean; message: OrderedMessage }> {
    const dKey = dedupKey(room, messageId)

    // (1) Idempotency gate FIRST: only the first caller for this (room, messageId)
    // wins the NX write; concurrent retries all see the marker already present.
    const reserved = await redis.set(dKey, "pending", "EX", DEDUP_TTL_SECONDS, "NX")

    if (reserved === null) {
        // Duplicate: read back the ALREADY-STORED message instead of burning a
        // new seq or fabricating a new entry.
        const existingRaw = await redis.get(dKey)
        const existingSeq = existingRaw !== null && existingRaw !== "pending" ? Number(existingRaw) : null
        if (existingSeq !== null) {
            const members = await redis.zrangebyscore(logKey(room), existingSeq, existingSeq)
            if (members.length > 0) {
                return { duplicate: true, message: JSON.parse(members[0]) as OrderedMessage }
            }
        }
        // Defensive fallback: marker exists but the log entry is missing (TTL
        // skew) — treat as duplicate with no recoverable payload.
        throw new Error(`duplicate messageId=${messageId} but original message not found`)
    }

    // (2) First writer: claim the next per-room seq atomically. Only genuinely
    // new messages ever call INCR, so seq stays gap-free.
    const seq = await redis.incr(seqKey(room))
    const message: OrderedMessage = { room, messageId, payload, seq }

    // (3) Store in a sorted set keyed by seq so range queries come back
    // pre-sorted in ascending order.
    await redis.zadd(logKey(room), seq, JSON.stringify(message))

    // Overwrite the dedup marker with the real seq so a later duplicate can
    // resolve back to this exact message.
    await redis.set(dKey, String(seq), "EX", DEDUP_TTL_SECONDS)

    return { duplicate: false, message }
}

// Missed-message backfill for reconnect: exclusive lower bound so a client
// that already has seq=N receives N+1.. and never re-sees N.
async function missedSince(room: string, afterSeq: number): Promise<OrderedMessage[]> {
    const members = await redis.zrangebyscore(logKey(room), `(${afterSeq}`, "+inf")
    return members.map((m) => JSON.parse(m) as OrderedMessage)
}
