class TrieNode {
    children: Map<string, TrieNode> = new Map()
    isEnd = false
    freq = 0
}

class Trie {
    private root = new TrieNode()

    insert(word: string, freq: number): void {
        const normalized = word.toLowerCase()
        let node = this.root
        for (const ch of normalized) {
            let next = node.children.get(ch)
            if (!next) {
                next = new TrieNode()
                node.children.set(ch, next)
            }
            node = next
        }
        node.isEnd = true
        // Accumulate instead of overwrite — inserting the same word repeatedly accumulates frequency.
        node.freq += freq
    }

    suggest(prefix: string, limit: number): string[] {
        const normalized = prefix.toLowerCase()
        let node = this.root
        for (const ch of normalized) {
            const next = node.children.get(ch)
            if (!next) {
                // No matching child node -> no word can match this prefix.
                return []
            }
            node = next
        }

        // Prefix node located -> DFS the subtree to gather every complete word + freq.
        const candidates: { word: string; freq: number }[] = []
        const dfs = (n: TrieNode, path: string) => {
            if (n.isEnd) candidates.push({ word: path, freq: n.freq })
            for (const [ch, child] of n.children) dfs(child, path + ch)
        }
        dfs(node, normalized)

        return candidates
            .sort((a, b) => b.freq - a.freq)
            .slice(0, limit)
            .map((c) => c.word)
    }
}

// Self-check examples:
// const t = new Trie()
// t.insert("apple", 5)
// t.insert("apple", 3)
// t.suggest("app", 10) -> ["apple"], since freq accumulated to 8
//
// t.insert("MacBook", 10)
// t.suggest("mac", 10) -> ["macbook"], normalized to lowercase so it matches regardless of casing
//
// t.suggest("xyz", 10) -> [], no matching child node for 'x' right at the first step
```
