            clientMessageId: event.clientMessageId,
            orderId: event.orderId,
            productId: event.productId,
            quantity: event.quantity,
        })
    } catch (err) {
        if (err.code === "23505") {
            // A genuine duplicate (already processed) -> skip silently, do NOT throw.
            // The offset still commits normally since the function ends without error.
            return
        }

        // A REAL error (e.g. productId doesn't exist) -> isolate to DLQ,
        // do NOT throw to avoid infinite retry / head-of-line blocking.
        await this.kafkaProducer.send({
            topic: "order.created.dlq",
            messages: [
                {
                    value: JSON.stringify({
                        originalEvent: event,
                        errorMessage: err.message,
                        failedAt: new Date().toISOString(),
                    }),
                },
            ],
        })
        // No throw -> the original offset still commits, the partition doesn't stall.
    }
}
```
The key point: `clientMessageId` is used as a unique constraint at the database, so duplicate protection is guaranteed atomically by the DATABASE ITSELF, not by a manual `findOne` then `insert` at the application layer (prone to a race condition when multiple instances process concurrently). The `catch` branch clearly distinguishes two error types by Postgres error code: `23505` is a duplicate key — skip silently and do NOT throw; every other error is treated as a real failure, pushed to a dedicated DLQ topic with the failure reason for an operator to inspect later, and crucially the function still ends WITHOUT throwing in this branch — if it threw, the framework would retry that same failed event infinitely, locking up the whole partition (head-of-line blocking) since Kafka can't advance the offset past a message stuck retrying.

