declare function sha256(input: string): string
declare function canonicalize(payload: string): string

interface AuditEntry {
    index: number
    payload: string
    prevHash: string
    entryHash: string
}

const GENESIS = "GENESIS"

function verifyChain(entries: AuditEntry[]): { ok: boolean; brokenAtIndex: number | null } {
    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i]

        // Step 1: check prevHash's provenance is correct.
        const expectedPrevHash = i === 0 ? GENESIS : entries[i - 1].entryHash
        if (entry.prevHash !== expectedPrevHash) {
            return { ok: false, brokenAtIndex: entry.index }
        }

        // Step 2: recompute entryHash and match — catches edited content/hash.
        const recomputed = sha256(canonicalize(entry.payload) + "|" + entry.prevHash)
        if (recomputed !== entry.entryHash) {
            return { ok: false, brokenAtIndex: entry.index }
        }
    }
    return { ok: true, brokenAtIndex: null }
}

// Self-check examples:
// - a fully valid chain -> verifyChain(validChain) === { ok: true, brokenAtIndex: null }
// - entry at index 3 has its payload edited but the stored entryHash keeps the old value
//   -> verifyChain(tamperedChain) === { ok: false, brokenAtIndex: 3 }
```
The two checks inside the loop are NOT redundant with each other: step 1 (`prevHash` matches the previous entry's `entryHash`) confirms the LINK between two consecutive entries — catching the case where someone inserted/deleted an entry in the middle and forgot to update the following entry's `prevHash`; step 2 (recomputing `entryHash`) confirms this entry's own CONTENT hasn't been altered since it was written. Because each `entryHash` embeds `prevHash` (which is the hash of the previous entry) into itself, editing ONE entry in the middle makes step 2 fail RIGHT AT that entry — the function stops and returns `brokenAtIndex` at exactly that position, without needing to know what happens at the entries AFTER it (they would also fail in cascade if checked further, but stopping early at the FIRST break is what the prompt requires and is also the most useful information for whoever is investigating).

