declare function crc16(input: string): number

function extractHashTag(key: string): string {
    const open = key.indexOf("{")
    if (open >= 0) {
        const close = key.indexOf("}", open + 1)
        // Only treat it as a hash-tag when the substring between { and } is non-empty.
        if (close > open + 1) {
            return key.substring(open + 1, close)
        }
    }
    return key
}

function slotForKey(key: string): number {
    const target = extractHashTag(key)
    return crc16(target) % 16384
}

// Self-check examples:
// slotForKey("{user:1}.profile") === slotForKey("{user:1}.cart")  -> true, both hash "user:1"
// slotForKey("user:1.profile") !== slotForKey("{user:1}.profile") -> true, no tag hashes the whole key
// slotForKey("{}.profile")     -> hashes the literal "{}.profile" since the {} substring is empty, not a valid tag
```
The key point: `extractHashTag` only returns the substring inside `{...}` when `close > open + 1` — meaning there is AT LEAST one character between the braces; if no `{` is found, or the tag is empty (`{}`), it returns the whole key. `slotForKey` then calls `crc16` on exactly that extracted substring and takes the remainder mod 16384. With this function, the team can answer offline "do these two keys share a slot" before shipping a Lua script/multi-key command to the cluster, avoiding a CROSSSLOT error discovered late at runtime.
